const to = new Date();
to.setDate(to.getDate() - 1);
const from = new Date(to);
from.setDate(from.getDate() - 89);

return [{
  json: {
    date_from: from.toISOString().split('T')[0],
    date_to:   to.toISOString().split('T')[0]
  }
}];

// Build campaign name -> location_id lookup from Google Sheet
const sheetRows = $('Get Campaign Mapping').all();
const campaignMap = {};
const LOCATION_SLUG = {
  'West Republic':   'west-republic',
  'North Glenstone': 'north-glenstone',
  'North Lindbergh': 'north-lindbergh',
};
for (const row of sheetRows) {
  const name = (row.json['Campaign Name'] || '').trim();
  const loc  = (row.json['Location'] || '').trim();
  if (name && LOCATION_SLUG[loc]) {
    campaignMap[name] = LOCATION_SLUG[loc];
  }
}

function getSubLocation(campaignName) {
  return campaignMap[campaignName] || 'springfield';
}

const LOCATION_NAME = {
  'west-republic':   'West Republic',
  'north-glenstone': 'North Glenstone',
  'north-lindbergh': 'North Lindbergh',
  'springfield':     'Springfield',
};

const results = items[0].json.results || [];
const dateMap = {};
const campaignDayMap = {};

for (const r of results) {
  const date   = r.segments?.date || 'unknown';
  const cost   = Number(r.metrics?.costMicros || 0) / 1000000;
  const impr   = Number(r.metrics?.impressions || 0);
  const clks   = Number(r.metrics?.clicks || 0);
  const conv   = Number(r.metrics?.conversions || 0);
  const cId    = String(r.campaign?.id || '');
  const cName  = r.campaign?.name || 'Unknown';
  const subLoc = getSubLocation(cName);

  const dateKey = `${subLoc}::${date}`;
  if (!dateMap[dateKey]) dateMap[dateKey] = { subLoc, date, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  dateMap[dateKey].spend       += cost;
  dateMap[dateKey].impressions += impr;
  dateMap[dateKey].clicks      += clks;
  dateMap[dateKey].conversions += conv;

  const campKey = `${cId}::${date}::${subLoc}`;
  if (!campaignDayMap[campKey]) {
    campaignDayMap[campKey] = { subLoc, date, campaign_id: cId, campaign_name: cName, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  }
  campaignDayMap[campKey].spend       += cost;
  campaignDayMap[campKey].impressions += impr;
  campaignDayMap[campKey].clicks      += clks;
  campaignDayMap[campKey].conversions += conv;
}

const daily_rows = Object.values(dateMap).map(m => ({
  location_id:   m.subLoc,
  location_name: LOCATION_NAME[m.subLoc] || m.subLoc,
  date:          m.date,
  spend:         Number(m.spend.toFixed(2)),
  impressions:   m.impressions,
  clicks:        m.clicks,
  conversions:   m.conversions,
  cpl:  m.conversions > 0 ? Number((m.spend / m.conversions).toFixed(2)) : null,
  ctr:  m.impressions > 0 ? Number((m.clicks / m.impressions * 100).toFixed(4)) : 0,
}));

const campaign_rows = Object.values(campaignDayMap).map(c => ({
  location_id:   c.subLoc,
  location_name: LOCATION_NAME[c.subLoc] || c.subLoc,
  date:          c.date,
  campaign_id:   c.campaign_id,
  campaign_name: c.campaign_name,
  spend:         Number(c.spend.toFixed(2)),
  impressions:   c.impressions,
  clicks:        c.clicks,
  conversions:   c.conversions,
  cpl:  c.conversions > 0 ? Number((c.spend / c.conversions).toFixed(2)) : null,
  ctr:  c.impressions > 0 ? Number((c.clicks / c.impressions * 100).toFixed(4)) : null,
}));

return [{ json: { daily_rows, campaign_rows } }];

const credentials = $('Set Meta Credentials').first().json;
const convTypes   = String(credentials.meta_conversion_action_types || 'lead').split(',').map(s => s.trim());

const data = items[0].json.data || [];

const dateMap = {};
const campaignDayMap = {};

for (const r of data) {
  const date    = r.date_start || 'unknown';  // now a single day
  const actions = Array.isArray(r.actions) ? r.actions : [];
  const conv    = actions.filter(a => convTypes.includes(a.action_type)).reduce((s, a) => s + Number(a.value || 0), 0);
  const spend   = Number(r.spend || 0);
  const impr    = Number(r.impressions || 0);
  const clks    = Number(r.clicks || 0);
  const cId     = r.campaign_id   || '';
  const cName   = r.campaign_name || 'Unknown';

  if (!dateMap[date]) dateMap[date] = { spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  dateMap[date].spend       += spend;
  dateMap[date].impressions += impr;
  dateMap[date].clicks      += clks;
  dateMap[date].conversions += conv;

  const key = `${cId}::${date}`;
  if (!campaignDayMap[key]) {
    campaignDayMap[key] = { date, campaign_id: cId, campaign_name: cName, spend: 0, impressions: 0, clicks: 0, conversions: 0 };
  }
  campaignDayMap[key].spend       += spend;
  campaignDayMap[key].impressions += impr;
  campaignDayMap[key].clicks      += clks;
  campaignDayMap[key].conversions += conv;
}

const daily_rows = Object.entries(dateMap).map(([date, m]) => ({
  date,
  spend:       Number(m.spend.toFixed(2)),
  impressions: m.impressions,
  clicks:      m.clicks,
  conversions: m.conversions,
  cpl:  m.conversions > 0 ? Number((m.spend / m.conversions).toFixed(2)) : null,
  ctr:  m.impressions > 0 ? Number((m.clicks / m.impressions * 100).toFixed(4)) : 0
}));

const campaign_rows = Object.values(campaignDayMap).map(c => ({
  date:          c.date,
  campaign_id:   c.campaign_id,
  campaign_name: c.campaign_name,
  spend:         Number(c.spend.toFixed(2)),
  impressions:   c.impressions,
  clicks:        c.clicks,
  conversions:   c.conversions,
  cpl:  c.conversions > 0 ? Number((c.spend / c.conversions).toFixed(2)) : null,
  ctr:  c.impressions > 0 ? Number((c.clicks / c.impressions * 100).toFixed(4)) : null
}));

const accountName = data[0]?.account_name || 'West Republic';

return [{ json: { daily_rows, campaign_rows, account_name: accountName } }];

